var i=`0564-shurpa`;var t=`world-0564`;var a=`UZ`;var o=`central-asia`;var r=4;var s=135;var m={en:`Shurpa`,ua:`Шурпа`};var g={en:`A traditional dish from Uzbekistan, centered on lamb, yellow onion, carrot, turnip. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: ягнятина, жовта цибуля, морква, ріпа. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`lamb`,720,`g`],[`yellow-onion`,210,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 90 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 90 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:90,i:[[`water`,1450,`ml`],[`carrot`,280,`g`],[`turnip`,200,`g`],[`black-peppercorn`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`potato`,490,`g`],[`tomato`,260,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,28,`g`]]}];var u={slug:i,id:t,country:`UZ`,region:o,servings:4,minutes:135,title:m,text:g,steps:l};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,i as slug,l as steps,g as text,m as title};